INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('front-mission-online', 1505, '2005-05-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2v55.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scka2n.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Front Mission: Online', 'A multiplayer-only arcade shooter based on Square''s Front Mission universe of futuristic mecha warfare. Joining either the USN or OCU during the second Huffman conflict, you duke it out on online arenas in your Wanzer for fame and money, which you can use to further upgrade your Wanzer with new weapons and special upgrades. All strategy elements from the series are removed save from the mechanics of damage and action, and the game is played from a 3rd person perspective similar to other 3d action titles. Registration to Square''s PlayOnline service and a monthly free is required for playing. The game has built-in support for VoIP.' FROM games WHERE igdb_id = 1505 ON CONFLICT (game_id, language_code) DO NOTHING;
