INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bomberman-kart--2', 198189, '2005-04-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5u64.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1lki.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman Kart', 'A racing game using simulated 3D in the vein of OutRun or Rad Racer, now with a rainbow of Bombermen in the drivers'' seats! Race against five opponents across three difficulties of Grand Prix, for a total of six courses. Racers can collect items from question mark panels, ranging from projectiles such as bombs, missiles and Slime Bombs, to situational items like landmines, shields and nitro boosts. There are six different colours of Bomberman and three karts to choose from, each with their own unique stats. Alongside the Grand Prix, you can race any track alone in the Time Trial mode and aim to beat your personal beat. Records for both Grand Prix and Time Trial can be uploaded to a national server.' FROM games WHERE igdb_id = 198189 ON CONFLICT (game_id, language_code) DO NOTHING;
