INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer 40,000: Space Hulk', 'This is a mobile version of the popular strategy board game from Games Workshop company! Everything just as in the original: two fighting races (Space paratroopers and Genestealers), weapons, locations and space battles full of adrenaline! The game has high quality graphics and sound which will guarantee absolutely new unforgettable feelings. The combination of step-by-step strategy and arcade action creates unique original gameplay, and big amount of game modes will let you show yourself as a professional space warrior!' FROM games WHERE igdb_id = 74199 ON CONFLICT (game_id, language_code) DO NOTHING;
