INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Code Age Commanders: Tsugu Mono Tsugareru Mono', 'Code Age Commanders is an action role-playing game, It is part of the Code Age series, a franchise designed to span different interweaved titles in multiple platforms and media. Set in an "intraglobular world", a fictional hollow world , with people living on its internal surface. The center of the sphere is occupied by the "Central Code", a spherical structure which goes through a transformation called "Reborn" about every ten thousand years, destroying all life on the globe and allowing for the birth of a new one.' FROM games WHERE igdb_id = 91669 ON CONFLICT (game_id, language_code) DO NOTHING;
