INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urusei Yatsura: Endless Summer', 'A dating sim for the Nintendo DS based on the anime Urusei Yatsura. As Ataru Moroboshi, the player spends a month with other characters from the series, and the girl with the highest love rating at the end of the month falls in love with him.' FROM games WHERE igdb_id = 72697 ON CONFLICT (game_id, language_code) DO NOTHING;
