INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('age-of-empires-iii-collectors-edition', 239366, '2005-11-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co80rh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclh4n.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Empires III: Collector''s Edition', 'In this highly anticipated next installment in the Age of Empires franchise from Ensemble Studios, Age of Empires III places players in the time period of roughly 1500–1850, picking up where Age of Empires II: The Age of Kings left off. As players work to establish their empire, they take on the role of a European power struggling to explore, colonize, and conquer North and South America. Age of Empires III introduces exciting new gameplay elements, including the all-new Home City and an incredible combat system. Players have new civilizations to discover, random maps to conquer, and a single-player campaign unlike any other. Players also find stunning graphics as a result of a revolutionary graphics engine that pushes the limits of PC graphics technology in an entirely new way.' FROM games WHERE igdb_id = 239366 ON CONFLICT (game_id, language_code) DO NOTHING;
