INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SBK: Snowboard Kids', 'SBK: Snowboard Kids, released in Japan as Snowboard Kids Party (スノボキッズパーティー sunobo kizzu pātī?), is a snowboarding video game for the Nintendo DS released on November 22, 2005 in North America and two days later in Japan. It was also released in Europe on April 28, 2006. It is the fourth in the Snowboard Kids series following three previous games released on the Nintendo 64 and the PlayStation. Up to four people can play wirelessly with one game card. Though the name is the same as the other games, the characters are teenagers in this installment.' FROM games WHERE igdb_id = 47725 ON CONFLICT (game_id, language_code) DO NOTHING;
