INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWII: Soldier', 'WWII: Soldier or SOE: Operation Avalanche is a Europe-only low-budget PC and PlayStation 2 stealth/first-person shooter by Atomic Planet and Midas Interactive Entertainment. The PC version only has a German version currently known in existence. In the game an Allied spy infiltrates the Swiss Alps to rescue an American general who is held prisoner by the Germans.' FROM games WHERE igdb_id = 43590 ON CONFLICT (game_id, language_code) DO NOTHING;
