INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubblefish Bob', 'You''re Bob, and you must save your fishy friends by matching three same-colored bubbles before the fish inside reach their awful fate. Beware of giant piranha-like guppies waiting to gobble up your friends unless you can free them in time by breaking and matching the bubbles. Collect falling treasures to bolster your score and gain lives to free more fish.' FROM games WHERE igdb_id = 341063 ON CONFLICT (game_id, language_code) DO NOTHING;
