INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 70: The Kanshikikan', 'This simple series game puts the player in the role of a female forensic that has to solve a number of mysteries (10 cases) by heading to the crime scene and collecting evidence and fingerprints which are then handed off to an expert for analysis. Your job is to manage evidence and string together a correct picture of the crime; go off on the wrong path and your superiors will grow angry and take you off the case.' FROM games WHERE igdb_id = 124078 ON CONFLICT (game_id, language_code) DO NOTHING;
