INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Another Century''s Episode', 'Another Century''s Episode is the collaboration of Banpresto, best known for their Super Robot Wars franchise, and From Software, the makers behind the Armored Core series. The game is a fast-paced action title featuring characters, mecha and story elements from nine famous Japanese anime. However, while Super Robot Wars is known for combining super robots, like Mazinger Z, and real robots, like Mobile Suit Gundam, A.C.E. exclusively focuses on real robots (later games, however, have include 1-2 Super Robot series in their casts).' FROM games WHERE igdb_id = 9566 ON CONFLICT (game_id, language_code) DO NOTHING;
