INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ore-tachi Gesen-zoku', 'Ore-tachi Gesen-zoku is a series of 19 emulated arcade machine game titles from the 80s and 90s for PlayStation 2 published by Hamster and only available in Japan.[2] Of the 19 games, the last two – Thunder Cross (1988) and Trio the Punch (1990) – were previously never released on home platforms.' FROM games WHERE igdb_id = 324600 ON CONFLICT (game_id, language_code) DO NOTHING;
