INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto: Ninja Council 2 - European Version', 'Naruto: Ninja Council 2 European Version is the third instalment in the Ninja Council series and the first for the Nintendo DS. It was released in Japan as Naruto: Saikyō Ninja Daikesshu 3 for DS and in Europe as Naruto: Ninja Council 2 European Version.' FROM games WHERE igdb_id = 79297 ON CONFLICT (game_id, language_code) DO NOTHING;
