INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Hunters', 'Flashing blades, crazy combat action, beautiful sisters and deadly zombies. What more could you need? The dead has risen and only your sword skills will save you from the horro that awaits! -Battle through endless waves of shambling zombies. -Perfect your sword handling and send heads, legs and hands flying through the air. -Numerous items and pick-ups will aid you in your progress. Experience the exhiliration of battle as you take on an army of undead!' FROM games WHERE igdb_id = 21552 ON CONFLICT (game_id, language_code) DO NOTHING;
