INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adrenalin', 'Adrenalin is a arcade racer/management game published by 1C games. Adrenalin is a game that successfully blends the genres of thrilling adrenalin-pumping racing and an economic management sim. The aim of a player is to not only become the fastest driver around, but to be a talented manager as well. In the beginning of the game the player has to pick out one of the twelve beautiful young ladies. One of them even exists in reality - she is the winner of Miss Russia contest in 2003.' FROM games WHERE igdb_id = 65270 ON CONFLICT (game_id, language_code) DO NOTHING;
