INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'McDonald''s Video Game', 'McDonald''s Video Game is a parody of the business practices of the corporate giant McDonald''s, taking the guise of a tycoon-style business-simulation game. The game presents the player with four views: The farmland, the slaughterhouse, the restaurant and the corporate HQ. Through each of these views, decisions can be made which will affect the fate of the player''s company. In the game, the player takes on the role of a McDonald''s CEO by choosing whether or not to feed the player''s cows genetically altered grain, plow over rainforests or feed the player''s cattle to other cattle (a practice known to spread mad cow disease). The player can also choose advertising strategies and public official corruption to counteract opponents of the player''s actions.' FROM games WHERE igdb_id = 148201 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 148201 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
