INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle of Elite', 'This puzzle game is controlled with the keyboard and mouse - the keyboard moves the character, while the mouse is used to place and destroy bricks. The first set of levels are built as tutorials to ease you into the game, so you don''t really need to read the manual. There are over 50 levels of increasing difficulty and a user-friendly level editor where you can create, edit and play your own levels. A ".lev" file is created for every custom level you build.' FROM games WHERE igdb_id = 125406 ON CONFLICT (game_id, language_code) DO NOTHING;
