INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('enigmi-dot-net', 327205, '2005-12-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co98dt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuylw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enigmi.net', 'Enigmi.net (now Enigmi.online) is a browser-based puzzle game where players progress through 91 increasingly challenging riddles. Originally released in 2005 and preserved in 2024, this Italian-language web puzzle requires players to solve each level by discovering a specific word or phrase that becomes part of the URL to access the next challenge. The game features a diverse range of puzzles that incorporate visual elements, audio clues, and logical reasoning. Players may need to use image editing software, audio tools, and web searching capabilities to uncover solutions. Each answer must be entered in lowercase without spaces or special characters, and while the game''s logical framework is in Italian, solutions can include words from other languages. With only 169 players having completed all levels since its launch, Enigmi.net offers both solo and group play experiences, supported by a Discord community where players can find hints when stuck. The game is designed to be accessible to all skill levels while providing a substantial challenge that rewards patience and investigative thinking.' FROM games WHERE igdb_id = 327205 ON CONFLICT (game_id, language_code) DO NOTHING;
