INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mew Mew Power: Cyniclon Invasion', 'Mew Mew Power: Cyniclon Invasion is a Flash game developed and published by 4Kids. The game is a Space Invaders clone based on the anime Tokyo Mew Mew, localized as Mew Mew Power in the west.' FROM games WHERE igdb_id = 328424 ON CONFLICT (game_id, language_code) DO NOTHING;
