INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Show do Milhão 2006', 'WILL YOU ACCEPT THE CHALLENGE? All the emotions of the television program Show do Milhão from SBT, with Silvio Santos are in this game, now with more than 20.000 questions. In this new 2006 edition you can play with up to 8 players on the same computer, or if you prefer you can play online, against real opponents over the internet, increasing your sense of competition, and trying to reach the highest scores in the Show do Milhão Hall of Fame.' FROM games WHERE igdb_id = 163341 ON CONFLICT (game_id, language_code) DO NOTHING;
