INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guilty Gear XX Slash', 'Guilty Gear XX Slash is the second updated version of Guilty Gear X2. Once again, the game''s balance was reworked by changing properties of certain moves and including new moves for some of the characters. Two new characters were introduced to the game, these being A.B.A, who debuted in Guilty Gear Isuka, and Order-Sol, who is Sol Badguy with an entirely different costume, and moveset.' FROM games WHERE igdb_id = 9144 ON CONFLICT (game_id, language_code) DO NOTHING;
