INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animaniacs: The Great Edgar Hunt', 'Animaniacs: The Great Edgar Hunt is a third-person action adventure, which brings the colourful and hysterical world of the Animaniacs wonderfully to life. Players must guide the Warner brothers and sister Wakko, Yakko and Dot through six levels in a quest to locate the hidden Edgar trophies. Each Animaniac has his or her own special abilities, and each must be used in order to fully explore the luscious landscapes.' FROM games WHERE igdb_id = 3786 ON CONFLICT (game_id, language_code) DO NOTHING;
