INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Life', 'Dream Life is a dedicated console life simulation game targeted at girls between the ages of 8 and 14 created by Hasbro and released in 2005. Dream Life is a game where players create a girl character, ranging from hair to clothes. They can also determine how smart, funny, athletic, creative or outgoing the girl character is.' FROM games WHERE igdb_id = 206922 ON CONFLICT (game_id, language_code) DO NOTHING;
