INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Ultimate Vol. 23: Project Minerva Professional', 'Using a variety of weapons classes you must progress through many varied missions, using your squad members to scout ahead, bomb targets, rescue hostages and ultimately defeat your enemy and free the world. Gain cash and experience by defeating your enemies. Use this to improve your arsenal, level up your squad and unlock new items to help in your mission.' FROM games WHERE igdb_id = 9712 ON CONFLICT (game_id, language_code) DO NOTHING;
