INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire From Heaven', 'A Christian text adventure game. The player plods along through environments as varied as the Wayside Chapel, an Angel Barracks, the Blackclaw Forest, and the redundant Catacomb Caves, sporadically taking in deeper wisdom from angelic mentors on side-branches or applying that wisdom against demonic tormentors encountered on the main path. When exploring destinations numerous nuanced navigational options are offered (cardinal directions vs. the standard "Continue on"), but generally only one or two are valid, making this game, narratively, akin to a fixed-rail shooter... only with praying in place of shooting' FROM games WHERE igdb_id = 73888 ON CONFLICT (game_id, language_code) DO NOTHING;
