INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-legend-of-white-whale', 243945, '2005-01-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6cem.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclxg8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of White Whale', 'Legend of White Whale is a role-playing game that focuses on a group of three mushroom friends on a quest to find "The White Whale," the legendary ship that brought their ancestors into the world. The village of Mushsnail is starting to dry up, and that would mean certain death for everyone who lives there. Frup-Foo (our hero) believes that if the mythical White Whale exists, he can keep the secret of a new beginning. But there is an evil afoot. Now that Mushsnail is starting to dry up, he has been left vulnerable to monsters that previously couldn''t enter the magic barrier. With each passing day, the village becomes more at risk. White Whale features turn-based rpg battles and an aerial world map. Each character has their own abilities, of course. Priss is the healer as well as the state spell caster. Frup is slower than the others, but has a powerful special attack and is the only character who can use items during battle. Chup is the fighter, and he can only ... well... fight! The game progresses in chapters. Each chapter takes place in the same world, just with a different goal.' FROM games WHERE igdb_id = 243945 ON CONFLICT (game_id, language_code) DO NOTHING;
