INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tony-hawks-american-wasteland-collectors-edition', 43395, '2005-11-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2g2e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6wp9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tony Hawk''s American Wasteland: Collector''s Edition', 'Now you can cruise through LA without loading levels or stopping gameplay in Tony Hawk''s American Wasteland. You can skate or BMX through a new story mode that takes you through all-new skate areas using tricks that have never appeared in previous Tony Hawk games. The cash that you earn can be used to customize your equipment and your skater by going to tattoo parlors and skate shops. Tony Hawk''s American Wasteland also includes a classic mode that features classic Tony Hawk Pro Skater maps and objectives. Included in this edition: - Tony Hawk''s American Wasteland - Two exclusive classic mode levels - Two exclusive secret characters - The "Making of Tony Hawk''s American Wasteland" documentary - A concept art gallery featuring creations by legendary artist Jimbo Philips' FROM games WHERE igdb_id = 43395 ON CONFLICT (game_id, language_code) DO NOTHING;
