INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imperia Online', 'Imperia Online is MMO strategy known for its deep gameplay. Build your capital, claim new territories by establishing provinces, trading posts and military encampments. Train your army to spy on the enemy and defend your Empire. With its pvp focus you can expect to become a part of an alliance and wage war against enemy players in competition for the title "Lord of the Realm"! Special weekly events, realms and tournaments are all present and further enrich your gameplay experience.' FROM games WHERE igdb_id = 33918 ON CONFLICT (game_id, language_code) DO NOTHING;
