INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bokujou Monogatari: Shiawase no Uta', 'Bokujō Monogatari: Shiawase no Uta is the fourteenth title of Bokujō Monogatari series to be released for Gamecube. It was never released outside of Japan. The game was updated eight months later with the release of Bokujō Monogatari: Shiawase no Uta for Wārudo. Natsume localized the updated version of the game under the name Harvest Moon: Magical Melody. The game contains several differences: Jamie is not marriageable. Smaller capacity for the shelf and the fridge. The game balance has not been readjusted. Contains several bugs and freezes.' FROM games WHERE igdb_id = 206848 ON CONFLICT (game_id, language_code) DO NOTHING;
