INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ai to Roudou no Hibi', 'Ai to Roudou no Hibi is a surreal mobile life simulation game where the player takes control of a bear as they get a job and live out their short 31 day life. The bears job consists of rolling a ball to a goal, avoiding holes and obstacles. Failing to do so results in some strong words their boss and a cut to their wages.' FROM games WHERE igdb_id = 288085 ON CONFLICT (game_id, language_code) DO NOTHING;
