INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('schnappi-3-fun-games', 96526, '2005-07-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co53l1.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Schnappi: 3 Fun-Games', 'From the depths of the Internets it emerged and was from then on no more from the German medium landscape to be excluded: Schnappi, the small crocodile of the Nile. The single was distinguished in Germany recently with double platinum, and also the not-German-language foreign country came in the meantime on the taste: In the Netherlands it made itself Schnappi already cosy at place 2 the single Charts. No question, Schnappi met the correct nerve with young and adults. And now the singing reptile opens itself to show also on the PC & Playstation. In three plays the player can make sure of the fact that this crocodile can do more than just singing. In Schnappi snatch! Schnappi makes what he can do best: it snatches! In this case there is insects, on which he foresaw it. But also with an allegedly so harmless booty highest watchfulness is announced. Because in 20 levels are not only harmless Brummer, but also stinging wasps. And to the researcher Schnappi may not go also into the net! Apart from a good reactivity of the player there above all Schnappis jump strength is in demand. With Schappi think! the player must exert the brain a little as birth aids, so that Schnappi from its egg can hop. And in Schnappi dance! the proof is finally begun that a genuine Popstar must be able to dance evenly also, in order to exist in this hard Business. Schnappi - 3 Fungames is a successful pastime for all fans of the green medium star.' FROM games WHERE igdb_id = 96526 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 96526 AND p.igdb_id = 7 ON CONFLICT DO NOTHING;
