INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Train Simulator: Keisei Toei Asakusa Keikyu-sen', 'Another in the series of Train Simulator FMV games developed by Ongakukan. This instalment features the connected networks of the Keikyu, Toei, and Keisei railways from Haneda Airport to Narita Airport, and introduces a new system of unlocking new train classes via spending points earned during the game.' FROM games WHERE igdb_id = 92249 ON CONFLICT (game_id, language_code) DO NOTHING;
