INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure II', 'Adventure II is an Atari 2600 homebrew developed by Curt Vendel as a fanmade sequel to Warren Robinett''s original 1979 Adventure. Vendel took inspiration from Ron Lloyd''s Atari 5200 Adventure homebrew, also called Adventure II, which was in early development at the time. Vendel''s Adventure II was released on the Atari Flashback 2 plug-and-play console in August 2005, and has been included in every subsequent Flashback console. It was also included in Atari Flashback Classics on the Nintendo Switch, and Atari Flashback Classics Vol. 3 on PlayStation 4 and Xbox One. Like the original game, the player controls a solid square avatar, navigating through mazes and collecting items in order to find the Enchanted Chalice and return it to the Golden Castle. The three dragons and bat also return, this time much more aggressive. The map is also larger, boasting 47 rooms.' FROM games WHERE igdb_id = 40783 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 40783 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
