INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty 2: Collector''s Edition', 'A special edition of the second entry into the fray of WWII. Featured in addition to the game are bonuses such as game trailers and concept art, mission walkthroughs and DVD-style developer commentary (with notes on the historical accuracy as well as game play tips), a narration by veteran Ranger Len Lomell about the assault on Pointe du Hoc, interviews and recording footage with the voice-over cast, and behind-the scenes footage with the developer.' FROM games WHERE igdb_id = 292790 ON CONFLICT (game_id, language_code) DO NOTHING;
