INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wrestling-encore', 92737, '2005-12-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa67k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/syu1wx4caqrynvkmqqf9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrestling Encore', 'Everything so far has been a warm-up act... get ready for the main event! Following the cult success of 2004''s Wrestling MPire, the world''s biggest and most innovative wrestling simulator is back and better than ever for a Wrestling Encore! It takes the same revolutionary contract-driven career mode and fulfills its potential with improved graphics, animation, sound, and gameplay. Create your own wrestling wannabe from scratch, and then immerse them in a gigantic universe of over 200 wrestlers spread across 6 major promotions. Negotiate the big-money deals that will make you rich, win the high-profile matches that will make your name, and develop the backstage relationships that will determine your fate - as you play through an endless schedule of possibilities. Or simply blow off steam with the wildest in-ring action that a PC can handle - featuring up to 30 characters on screen, and up to 100 fully interactive items and weapons!' FROM games WHERE igdb_id = 92737 ON CONFLICT (game_id, language_code) DO NOTHING;
