INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Invisible Sign: Isu - Nemureru Mori', 'It is still a story about the mystery of the unsolved incident happened 20 years ago that has something to do with present suspicious events, but the main difference is in the big number of different endings. There are also new characterswith their own stories and endings and the possibility to see the true end with the eyes of another protagonist.' FROM games WHERE igdb_id = 221030 ON CONFLICT (game_id, language_code) DO NOTHING;
