INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Genius: Biology', 'Genius: Task Force Biologie is an educational strategy game in which you are an UN-contractor. Your mission is to renaturate desolated landscapes in Africa, Indonesia, America, on the Mediterranean and Germany. To accomplish this, you direct a task force of scientists. After the renaturation you have to build up an agricultural production company, with many structures, that uses the natural resources wisely and researches the biotechnological progress.' FROM games WHERE igdb_id = 70769 ON CONFLICT (game_id, language_code) DO NOTHING;
