INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Pierrot', 'Crazy Pierrot is a Japanese Flash screamer game designed and scripted by Yoshiaki Ogiwara. The player''s goal in the game is to control a clown and catch the apples falling from the sky, while dodging the skulls - catching one of them is an instant game over. However, the game''s description says that the game is actually cursed and that the player should not get a 4000+ score.' FROM games WHERE igdb_id = 339487 ON CONFLICT (game_id, language_code) DO NOTHING;
