INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glimmerati', 'In the game''s story, the player is a wealthy heir who meets with another wealthy man one day, and he admires the player''s skill in driving. He invites the player to compete with Club Glimmerati, an exclusive gathering of famous and rich people who race in the public streets for fun.' FROM games WHERE igdb_id = 6263 ON CONFLICT (game_id, language_code) DO NOTHING;
