INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokimeki Factory Vol.1', 'Tokimeki Factory is a storytelling game developed by ActMind and published by Konami for PC and MacOS. The game allows players to create and write their own scenarios featuring one of six boys. Players can customize the backgrounds, boys'' clothes, dialogue, and music. Over 1,000 lines of voiced dialogue were recorded for the game. It was split into two volumes (Tokimeki Factory Vol. 1 and Tokimeki Factory Vol. 2), each featuring different characters. A complete box set featuring both volumes was also released.' FROM games WHERE igdb_id = 221600 ON CONFLICT (game_id, language_code) DO NOTHING;
