INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('summon-night-ex-these-yoake-no-tsubasa', 69844, '2005-08-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co69hr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sccqtd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summon Night Ex-These: Yoake no Tsubasa', 'Summon Night Ex-These is a spin-off of the Summon Night series, released for the Playstation 2 on August 4, 2005 . The player takes control of Leonus & Ainna, two adventurers that wake up in a cave to find out that not only they lost their memories, but are also sharing the same body. They go on a journey to look for the mysterious Nova, who might know something about their past. The character you choose at the start becomes the lead in the story and the true owner or the body, the other one still participates in the plot as a sub-protagonist. Normally, they are not able to talk with each others, but using the “Stone of the Everlasting Night” they can meet inside an artificial world.' FROM games WHERE igdb_id = 69844 ON CONFLICT (game_id, language_code) DO NOTHING;
