INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted Waters Online', 'Discover yourself in the “Age of Discovery” where you’ll sail out into the uncharted waters! Discover real historical artifacts and mystical legends! Start a company and make enormous fortunes! Fight in fierce sea battles! Whatever your play style, you can play who you want and how you want in UWO!' FROM games WHERE igdb_id = 102570 ON CONFLICT (game_id, language_code) DO NOTHING;
