INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol.86: Menkyo Shutoku Simulation - Kaiseidouro Koutsuu-hou Taiouban', 'The Menkyou Shutoku Simulation is a simulation game about getting a driving license. the game features over 3000 different questions, the game features over his previous version (Simple 2000 Series Vol.25 - The Menkyo Shutoku Simulation) the traffic laws updates of the year 2005. The game features ordinary car license, ordinary motorcycle license, limited ordinary motorcycle license & moped license.' FROM games WHERE igdb_id = 203325 ON CONFLICT (game_id, language_code) DO NOTHING;
