INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ghost-in-the-shell-stand-alone-complex--2', 114138, '2005-09-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1poq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5zfa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost in the Shell: Stand Alone Complex', 'Ghost in the Shell: Stand Alone Complex, released in Japan as Kokaku Kidotai: Stand Alone Complex - Domain of the Hunters, is a first-person shooter video game based on the cyberpunk anime series Ghost in the Shell: Stand Alone Complex and a sequel to the first Ghost in the Shell: Stand Alone Complex game of the same title, developed by G-Artists and published for the PlayStation Portable by Sony Computer Entertainment and Bandai in 2005. It was released in Japan on September 15, 2005, in Europe on October 21, 2005 distributed by Atari Europe, and in North America on October 26, 2005, but under the same name as the original PS2 game causing confusion and misinterpreting as a port. Ghost in the Shell features first-person shooter gameplay. Customizable Tachikoma sentient tanks, which can operate independently as AI characters or be ridden inside by players, accompany the player at all times. Playable characters include Motoko Kusanagi, Batou, Togusa, and Saito. All levels can be played by all characters. Aramaki is also available for multiplayer matches. All characters have varying statistics which can affect how a game plays out, for example Batou has more health than other players and Saito holds sniper rifles steadier than others. In addition, Tachikoma robots can act as an AI companion, and players can select from four Tachikoma "characters", balanced, aggressive, intelligent and humorous. Controls are similar to other first person shooter games on the platform, such as Coded Arms and Medal of Honor: Heroes.' FROM games WHERE igdb_id = 114138 ON CONFLICT (game_id, language_code) DO NOTHING;
