INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mabino Style', 'Mabino Style is a dating simulation visual novel set in a fantasy world of magic. You are a student in training at a magic school and during tour training schedule you will get to meet several young female witches with whom you will learn various magic and get to know each other in the process. Magic training is done via several different mini-games such as using cards or magic wand.' FROM games WHERE igdb_id = 76084 ON CONFLICT (game_id, language_code) DO NOTHING;
