INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('guild-wars-game-of-the-year-edition', 27842, '2005-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ciqv23wj3hoel0wqciwl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hydo1iiselvwc9tcf80d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guild Wars: Game of the Year Edition', 'An award-winning online fantasy epic awaits. No Subscription Fees!  Take your first step into Guild Wars®, the award-winning fantasy online roleplaying game enjoyed by millions of players. Across Tyria, the human kingdoms are under attack by the vicious Charr. As a young hero caught between the powerful will of King Adelbern and the rebellious Prince Rurik, you are called upon to defend humanity. Will you become an instrument of the ancient prophecy or be crushed beneath it? Rally your strength and the power of your guild to establish your legend.' FROM games WHERE igdb_id = 27842 ON CONFLICT (game_id, language_code) DO NOTHING;
