INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Ages 2500 Vol.17: Phantasy Star Generation 2', 'This game is much like Phantasy Star Generation: 1, except that it stands as a remake of Phantasy Star II. Like the first "Generation" a number of tweaks were made to bring it in line with more modern RPGs, and the graphics and sound have been updated. Also included is an emulated version of the Mega Drive Phantasy Star II (the Japanese version).' FROM games WHERE igdb_id = 129891 ON CONFLICT (game_id, language_code) DO NOTHING;
