INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slyder Adventures', 'Join Slyder and his friends on a topsy-turvy adventure through a world of mazes packed with fun, excitement, and danger! Tilt and turn Slyder''s world and watch him tumble to the finish line. Featuring over 150 challenging levels, more than 30 secrets to discover, and four unique and dazzling worlds, Slyder Adventures is an adorable delight for the entire family. So, turn your thinking cap upside down and discover a world of fun.' FROM games WHERE igdb_id = 338548 ON CONFLICT (game_id, language_code) DO NOTHING;
