INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riff: The Music Trivia DVD Game', 'RIFF is the music game that will rock your memories. We''ll challenge your recall on groups, music videos, songs, lyrics, album covers, and more. From Grunge to Rap, Pop to Heavy Metal, Classic rock to Alternative, we''ve got it all! Two teams compete through a series of puzzles, videos, and challenges to see who really is ready to face the music.' FROM games WHERE igdb_id = 360767 ON CONFLICT (game_id, language_code) DO NOTHING;
