INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Romancing SaGa: Minstrel Song', 'A grounds-up remake of Romancing SaGa that carries over the general aesthetic and style of Unlimited SaGa, featuring changes to the battle and class systems, the removal and addition of certain characters, as well as the addition of several elements that had originally been planned for the SNES Romancing SaGa 2 (the story, however, remains largely the same).' FROM games WHERE igdb_id = 141296 ON CONFLICT (game_id, language_code) DO NOTHING;
