INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strom The House', 'Storm the House is a classic, fast-paced Flash defense game where players act as a lone sniper protecting an adobe house from relentless waves of stickman attackers. Gameplay focuses on shooting advancing enemies with a mouse-controlled rifle, using money earned to buy upgrades like stronger weapons, defensive walls, hired gunners, and missile silos.' FROM games WHERE igdb_id = 389503 ON CONFLICT (game_id, language_code) DO NOTHING;
