INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kidou Gekidan Haro Ichiza: Haro no Puyo Puyo', 'Gundam-flavored Puyo Puyo. Kidou Gekidan Haro Ichiza: Haro no Puyo Puyo is a Puyo Puyo game based on the Mobile Suit Gundam franchise, the original TV series in particular. Puyos are replaced by Haros, and several Gundam characters are playable. The game features a story mode, a verses mode, and a survival mode where random characters throw garbage Haros into the player''s field. Whenever a chain is completed, the chosen character will shout a famous phrase from the anime series; the game provides a large number of phrases that can be assigned to each character by the player.' FROM games WHERE igdb_id = 49645 ON CONFLICT (game_id, language_code) DO NOTHING;
