INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fullmetal Alchemist 3: Kami wo Tsugu Shoujo', 'Fullmetal Alchemist 3: Kami o Tsugu Shōjo is the third Fullmetal Alchemist video game for the PlayStation 2 and an RPG continuation of the series of Square Enix games. The first two games in the series are Fullmetal Alchemist and the Broken Angel and Fullmetal Alchemist 2: Curse of the Crimson Elixir. Unlike the first two games, this game is not released outside Japan.' FROM games WHERE igdb_id = 57443 ON CONFLICT (game_id, language_code) DO NOTHING;
