INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flygirrl', 'Fly Girrl is a 2D side-scrolling platform game where a girl in a club needs to jump on dorks to get their drinks and gain points. They want to feel up the girl, so she has to be careful not to get too close or a life is lost. More point are earned by taking out guys in succession. The men are spread out over the level and there are platforms at different heights to reach them. Each level contain a random element: one of four background colors and a random tune.' FROM games WHERE igdb_id = 340150 ON CONFLICT (game_id, language_code) DO NOTHING;
