INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suguri', 'Experience the rush of battle with the fan acclaimed videogame "Suguri" - one of the most unique side-scrolling shooter titles ever created by doujin game developer Orange_Juice. Showcasing beautifully rendered designs and backgrounds, innovative weaponry, captivating gameplay action, and a cool techno-trance soundtrack, "SUGURI" is a must-have, must-play doujin game.' FROM games WHERE igdb_id = 80489 ON CONFLICT (game_id, language_code) DO NOTHING;
