INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ford-mustang-the-legend-lives', 43306, '2005-05-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9bmo.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ford Mustang: The Legend Lives', 'Since April of 1964 the Ford Mustang has sold over 8 million vehicles and has generated a strong following of enthusiasts, aftermarket manufacturers, websites, and publications - all dedicated to this iconic vehicle. "Ford Mustang" provides incredible graphics and "pick up and play" gameplay - at a value price. Drive the hottest cars from the 40 year history of the Mustang on 22 tracks in 7 U.S. cities. The game features 40 authentically rendered production, concept and racing models from 1964 to 2005, offering arcade-style racing physics and realistic AI, from opponents as well as from obstacle traffic. Compete in "coin-op" style Challenges or Career Mode to unlock new cars, tracks and game modes while testing your skills to the limit. Also included: split screen Multiplayer support for Head-to-Head racing.' FROM games WHERE igdb_id = 43306 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 43306 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
