INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trans''2: Boku to Atashi to Koibito to', 'Trans''2: Boku to Atashi to Koibito to is a cross-gender feminine-expression themed eroge developed by Catear. Protagonist Shinobu is introduced to the world of cross-gender expression by childhood friend Mizuki. The game includes both ADV-style visual novel sections and "dress-up" sections where players are able to choose how Shinobu goes out into the city.' FROM games WHERE igdb_id = 228303 ON CONFLICT (game_id, language_code) DO NOTHING;
