INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nursery-rhyme', 69306, '2005-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6948.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sce9nb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nursery Rhyme', 'Nursery Rhyme is a Japanese adult visual novel developed by Lump of Sugar and released on November 25, 2005 for Windows. The game, taking place 500 years after the events of Tayutama: Kiss on my Deity, is set in a fictional Japan where the existence of magic has been recognized by society, and thus has been the subject of much research. Magic is also applied to everyday life; for example, stuffed toys are able to talk. Users of magic must wear a special ring which controls their powers, and are urged to blend in with society. Despite Nursery Rhyme being set in the future, Japan''s culture is depicted as unchanged for the most part. Many of the characters attend Shousei Gakuen, a prestigious all-girls school which provides its students with magic classes, as well as academic courses. Shousei Gakuen hosts a female-dominated sport event known as Sophilos.' FROM games WHERE igdb_id = 69306 ON CONFLICT (game_id, language_code) DO NOTHING;
