INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Herbie: Fully Loaded', 'Inspired by Walt Disney Pictures'' feature film Herbie: Fully Loaded, the action-packed video game thrusts players into the high-octane world of 3D stock car racing. The video game offers fans a chance to slip behind the wheel of one of the world’s most beloved cars, Herbie the Love Bug, while enjoying fun power-ups, personalized racing moves, hazards and free replays of unlocked races.' FROM games WHERE igdb_id = 6434 ON CONFLICT (game_id, language_code) DO NOTHING;
