INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Online', 'Yu-Gi-Oh! Online is an online PC game released in November 2005 by Konami, based on the Yu-Gi-Oh! Trading Card Game, players of the game can duel each other online. Later two versions of the game has been released, Yu-Gi-Oh! Online: Duel Evolution and Yu-Gi-Oh! Online 3: Duel Accelerator.' FROM games WHERE igdb_id = 51279 ON CONFLICT (game_id, language_code) DO NOTHING;
