INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario: Fushigi no Koro-koro Party 2', 'Super Mario: Fushigi no Koro-koro Party 2 is the sequel to Super Mario: Fushigi no Korokoro Party developed by Capcom. This arcade game is a Mario Party game released only in Japan and has all the usual characters playable. Eight to sixteen people could play the game. It is the eleventh installment in the series overall.' FROM games WHERE igdb_id = 132034 ON CONFLICT (game_id, language_code) DO NOTHING;
