INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-seal-hunter', 345555, '2005-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9vdf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scx05j.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Seal Hunter', 'Very bloody game Seal Hunter, where you will have to act as a defender of the territory from all sorts of sea creatures (and not only). Blood, plenty of weapons and the possibility to play in two make the game worth your attention. A growing population of seals is destroying all the fish in the sea. The fishermen are left without a catch, and the seals meanwhile continue to multiply and eat all the fish. Two fishermen decide to take control of the situation and get rid of the extra mouths, thus preserving the once fish-rich ocean. Along with the seals, they need to kill penguins, baby seals, and, for some reason, sea turtles and polar bears. In general, armed with a considerable arsenal, fishermen go hunting. Seal Hunter game at first glance is simple and uncomplicated, but behind all this hides a rather complex timekiller. You can''t act on the fly, you won''t get far. In the game you need to tactically calculate literally everything. How much ammo is left, and when the boss will appear, what weapon to buy next; what is better to kill a penguin with, and what is better to kill a seal with; how to keep a full horn of ammo in the machine gun to kill a dozen penguins in a few seconds, etc.' FROM games WHERE igdb_id = 345555 ON CONFLICT (game_id, language_code) DO NOTHING;
