INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Team Turbo', 'Pokémon: Team Turbo is a game compilation intended for young children, themed after the Pokémon franchise. The game contains six races and five mini-games such as Bulbasaur''s Domino Dash and Squirtle''s Door Dilemma, which upon winning, gives the player special powers to use in the races. The controls are very simple: the mouse is used to steer and the mouse buttons are used to activate the powers.' FROM games WHERE igdb_id = 64034 ON CONFLICT (game_id, language_code) DO NOTHING;
