INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('drod-journey-to-rooted-hold', 9085, '2005-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2q2u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvof.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DROD: Journey to Rooted Hold', 'Swordplay and puzzles combine in this thinking man''s dungeon crawl. It''s simple to learn, with just a handful of commands to master. But the unique gameplay provides an amazing depth. A detailed overhead view shows monsters, obstacles, and other game elements. You have as much time as you like to contemplate your next move. So this is a good game for relaxing, but also terrifically involving once you get started. You''ll be hooked by the story of Beethro and his troublesome nephew, Halph. Our heroes set off on a harmless jaunt, but end up far below the surface, chased by a clownish madman. They begin to uncover a vast, underground bureaucracy, and things only get stranger the further they delve. You''ve got over 350 rooms ahead--each one a singular challenge for you to conquer.' FROM games WHERE igdb_id = 9085 ON CONFLICT (game_id, language_code) DO NOTHING;
