INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('simple-2000-series-vol-85-the-sekai-meisaku-gekijou-quiz', 203324, '2005-08-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4tea.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch7i5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 85: The Sekai Meisaku Gekijou Quiz', 'The Sekai Meisaku Gekijou Quiz: The 85th volume of D3''s Simple 2000 series is a quiz game featuring questions from 22 years of anime, totaling over 23 productions. The game includes over 5000 questions from such properties as Peter Pan no Bouken, Romeo no Aoi Sora, Trap Ikka Monogatari, and Flanders no Inu. Gameplay modes include Memorial Quiz, where you select from 8 works and answer questions set in multiple stages that follow the production''s storyline, Solo Quiz, where you select from 8 works and 6 genres and work to keep a life meter from reaching zero, and Travel Quiz in which two players answer questions pulled from eight productions simultaneously. The game includes summaries of the original works which provide hints to performing well in the question sessions.' FROM games WHERE igdb_id = 203324 ON CONFLICT (game_id, language_code) DO NOTHING;
