INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Globy', 'Globy is an indie game that features a fantasy world, delivered in 3D, in which you will have to find some magical globes that can be used to prevent a demon invasion. Globy is about a prince named Dreamy who has a vision in which demons plan to take over his world. Asking for help from the magi, he is told that he needs to find 24 magical orbs and only with those can he stop the invasion of his realm. And that’s about it, the prince sets off to locate them.' FROM games WHERE igdb_id = 326061 ON CONFLICT (game_id, language_code) DO NOTHING;
