INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fishing Fantasy: Buzzrod', 'Possum, an archaeologist from the Kingdom of Emgrand, does no research and does nothing but fish. One day, while out on an adventure , possum finds a note in his missing uncle''s book about a mysterious ancient civilization that worship fish as messengers of gods. Possum sets out on a journey with his favorite rod in order to get closer to his admired uncle, a famous archaeologist, and above all, to meet a fish he has never seen before.' FROM games WHERE igdb_id = 301798 ON CONFLICT (game_id, language_code) DO NOTHING;
