INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wagamama Fairy: Mirumo de Pon! DokiDoki Memorial Panic', 'Wagamama Fairy: Mirumo de Pon! DokiDoki Memorial Panic is an adventure video game which was was developed and published by Konami and released for Game Boy Advance on September 8, 2005 in Japan. This game is based of the Manga and Anime series Selfish Fairy Mirumo De Pon!!, the game blends romantic comedy with magical mischief. Players interact with beloved characters from the series through dialogue choices, mini-games, and story-driven events, all wrapped in a whimsical fantasy setting' FROM games WHERE igdb_id = 284596 ON CONFLICT (game_id, language_code) DO NOTHING;
