INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman Begins: Fast Pursuit', 'MULTI SCREEN TECHNOLOGY TAKES YOUR GAME TO THE NEXT LEVEL! - Exciting multi screen technology lets you view a map on one screen while driving the Batmobile through the streets of Gotham City on the other! - Map plots your location and gives advance notice of bad guys hiding out behind buildings. Defeat them by pressing the Throw button to throw Batarangs! - But be aware of approaching road blocks and barricades on the driving screen. Control the fate of the Batmobile by moving left or right to avoid oncoming obstacles or press the Jump button to activate this feature just like the Batmobile in the movie! - Auto shut off after 30 seconds of no play.' FROM games WHERE igdb_id = 245554 ON CONFLICT (game_id, language_code) DO NOTHING;
