INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop Station', 'The original Pop Station is an LCD-based handheld with a casing which copies a PlayStation Portable. The games play like old Tiger/Game & Watch-style games, with only one game selectable at once. Some other different handhelds were released under the name of Pop Station, but they use a different technology, the same as the Brick Games.' FROM games WHERE igdb_id = 289090 ON CONFLICT (game_id, language_code) DO NOTHING;
