INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventures in the Galaxy of Fantabulous Wonderment', 'Adventures in the Galaxy of Fantabulous Wonderment is a humorous adventure game following unwilling earthling Daniel Gordon in his adventures across space. The game features a mix of point-and-click adventure gameplay, a trading simulator, turn-based space battles, several minigames, and the odd ethical conundrum.' FROM games WHERE igdb_id = 23739 ON CONFLICT (game_id, language_code) DO NOTHING;
