INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outlaw Volleyball: Remixed', 'No Shoes. No shirts. No mercy.  50 Tour Events  Propel your team to the top  10 Extreme Courts  From the beach to the Big House  Multiplayer Action Including Xbox Live!  Do it anywhere, anytime, with anyone.  Quick, Intense Gameplay  Guaranteed to make your palms sweat.  16 Outrageous Characters  With their own playing styles and unique skills  Beat Your Opponent Senseless  Gain MOMENTUM for turbo moves.' FROM games WHERE igdb_id = 43628 ON CONFLICT (game_id, language_code) DO NOTHING;
