INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixel Chix', 'Pixel Chix was a handheld life simulation game released in 2005 by Mattel that was aimed at young children. The game was set in a plastic dollhouse and was similar to Tamagotchi in that they have a LCD screen and control buttons, although they are larger. The game is centered around interacting with a digital girl and doing activities with her, which includes feeding her, playing games, dressing her up, going out, sending her to bed and more. As you played, you would unlock new items and activities.' FROM games WHERE igdb_id = 296823 ON CONFLICT (game_id, language_code) DO NOTHING;
