INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tantei-kibukawa-ryousuke-jiken-tan-vol-3-shisha-no-rakuen', 293903, '2005-01-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7zeu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scriah.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Kibukawa Ryousuke Jiken-tan: Vol. 3 - Shisha no Rakuen', 'Murders occur one after another in the paradise of an amusement park The mystery deepens... A creepy threatening letter... You must solve the case with your own hands! Several months have passed since the nightmare at Kairoukan. Ikuo, who is struggling for ideas, visits his friend, Kikugawa. At the office for the first time in a while, a beautiful secretary from the popular amusement park "Shangri-La" who calls herself "Kikukawa Haruna" comes to consult with them. The request she makes is to provide security and investigate the cult-like threatening letter sent to the amusement park and the creepy prank that is similar to it. However, the company president, Kimijima Hiroshi, wants the matter to be handled confidentially and without telling the police. Not knowing the details and feeling suspicious, Ikuo and Izuna decide to head to Shangri-La. However, contrary to Ikuo and the others'' expectations, the mysterious person''s crimes continue. The blackmailer''s unexpected plan closes in on Ikuo! An invitation from paradise brought by a beautiful secretary.... And so begins a feast called judgment.... Who is the mysterious blackmailer?! This is a "command selection" adventure game in which you read the text from the perspective of Ikuo, choose the actions you deem appropriate, and lead the case to a resolution.' FROM games WHERE igdb_id = 293903 ON CONFLICT (game_id, language_code) DO NOTHING;
