INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Mario: Vitamin Toss', 'Dr. Mario: Vitamin Toss was an online Flash advergame published by Nintendo to promote Dr. Mario & Puzzle League for the Game Boy Advance. It was available to play on the game''s official website, as well as in the Nintendo Arcade section of nintendo.com. The game departs from the puzzle-driven gameplay of the Dr. Mario series, but nevertheless still has in view defeating viruses using capsules.' FROM games WHERE igdb_id = 231636 ON CONFLICT (game_id, language_code) DO NOTHING;
