INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truck Racing 2', 'Take control of more than two tons of racing power, hurtling along the track at 150mph! Truck Racing 2 gives you all the action of racing these massive machines, combining intuitive handling with astounding realism. You''ll have to race hard in order to beat aggressive opponents who won''t hesitate to use all of their bulk to shunt you off your line.' FROM games WHERE igdb_id = 43540 ON CONFLICT (game_id, language_code) DO NOTHING;
