INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Kim Possible 3: Team Possible', 'Based on Disney''s animated series Kim Possible, Team Possible follows Kim and Ron Stoppable as they battle villains, including Senor Senor, Monkey Fist, and Dr. Drakken. During the game, you can switch between Kim and Ron, and you can use their unique gadgets to complete objectives. Kim Possible 3: Team Possible features single- and multiplayer modes, as well as collectible trading cards and unlockable minigames.' FROM games WHERE igdb_id = 49186 ON CONFLICT (game_id, language_code) DO NOTHING;
