INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Velsabor', 'Velsabor is a game by Lachsen, started in the year 2002 and first released as a demo in 2005. It is classical RPG and is often cited as one of the best German RPG-Maker games ever to be released and won several community awards. A final demo was released in 2013 before the game got canceled for being to ambitious for an hobby project.' FROM games WHERE igdb_id = 241173 ON CONFLICT (game_id, language_code) DO NOTHING;
