INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tennis Titans', 'Hit the courts for some rowdy tennis fun with seven flavorful tennis characters! Featuring simple, easy-to-learn hitting and aiming, Tennis Titans brings together a crazy crew of colorful cartoon characters who all want the same thing - to be Court Champion. Plus, two great game modes means there''s more ways to win! Charming, delightful, and beautifully rendered, Tennis Titans is a challenging treat for the entire family.' FROM games WHERE igdb_id = 80353 ON CONFLICT (game_id, language_code) DO NOTHING;
