INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Golf: World Tour', 'Crazy family fun for up to 4 players! Devious courses. Colourful characters. Unique and exciting settings. Addictive gameplay... ...all adding up to hours of fun for you and your friends. Navigate moving obstacles, water hazards, extreme slopes, jumps and more over a range of themed courses crossing the globe, from the wild west to a pirate''s cove.' FROM games WHERE igdb_id = 43474 ON CONFLICT (game_id, language_code) DO NOTHING;
