INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ichigo Mashimaro', 'The visual novel, under the original title of Ichigo Mashimaro, was developed by ASCII Media Works for the PlayStation 2 based on the series under an all-ages CERO rating. The game was first released on August 11, 2005, and was re-released on March 8, 2007 under a ''The Best'' budget price.' FROM games WHERE igdb_id = 72557 ON CONFLICT (game_id, language_code) DO NOTHING;
