INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yogurting', 'Yogurting was a massively multiplayer online role-playing game. It was set in a modern-day setting with supernatural elements, and focused on the events occurring in the high schools Estiva and So-weol Academy. A mysterious event known as "Endless Vacation" caused teachers and entire schools disappear, and the students must discover who or what stands behind that phenomenon.' FROM games WHERE igdb_id = 166014 ON CONFLICT (game_id, language_code) DO NOTHING;
