INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('racing-battle-c1-grand-prix', 216591, '2005-05-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa350.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3tup.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Racing Battle: C1 Grand Prix', 'Genki''s racing games have typically fallen into the Shutokou Battle series, a collection of late-night racing games that put you on the highways surrounding Tokyo. The company''s latest PS2 racer, Racing Battle: C1 Grand Prix, maintains many of the same gameplay mechanics that Genki''s other games contain, but this time it takes the cars off of the streets and drops them onto proper racetracks. Racing Battle will contain licensed cars. The version on display only has a handful, including an RX-7, a Supra, an Integra, an Impreza, and an S2000. The car models in the game look decent. They''re nice and smooth, but they don''t seem to be quite as detailed as the car models in some other comparable racing games. Like most other racing games, Racing Battle has multiple camera angles. But the first-person angle is pretty interesting. From this view, you get indicators that show how hard you''re steering, accelerating, or braking. You also get a second, TV-style camera angle in a small window at the top of the screen. This is cool because it gives you a good idea of what''s going on near your car. It''s easy to see cars coming up behind you with this view and more effective than a standard rearview mirror. The gameplay in Racing Battle is roughly the same as what Genki has done with Shutokou and Kaido Battle series. Each car is associated with a fighting gamelike life meter, and the car in second place constantly loses pieces of its life meter. When one car runs out of "health," the race ends and a winner is declared.' FROM games WHERE igdb_id = 216591 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 216591 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
