INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Golf', 'Welcome to Crazy Golf, where seven different courses with six different holes will put your skills to the test. Guide your ball to the hole, navigating tricky corners and avoiding wacky obstacles along the way. Accurate controls give you complete control over the ball. Play alone or challenge your friends in multiplayer mode and show them who''s the true champ' FROM games WHERE igdb_id = 13531 ON CONFLICT (game_id, language_code) DO NOTHING;
