INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DK: King of Swing - Hurling for Distance', 'DK: King of Swing - Hurling for Distance was an online Flash advergame promoting DK: King of Swing for the Game Boy Advance. It was playable on the official DK: King of Swing website, as well as in the Nintendo Arcade section of nintendo.com, which was removed in newer versions of the website. The characters in the game are simply depicted as their inanimate artworks used for DK: King of Swing, with Donkey Kong being the playable character, Cranky Kong announcing the results, and a Mini-Necky spectating.' FROM games WHERE igdb_id = 231633 ON CONFLICT (game_id, language_code) DO NOTHING;
