INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demon Chaos', 'It is set in feudal Japan in the 16th century and revolves around a priestess who has been given eternal youth until she exterminates all the demons. She has been given charge of a mystical beast from the gods, Inugami, which is controlled by the player.  The game is in vein of the well known Dynasty Warriors series, in which the player battles crowd after crowd of hostile enemies. The unique aspect of the game is that up to 65,535 enemies can be on-screen at once.' FROM games WHERE igdb_id = 72861 ON CONFLICT (game_id, language_code) DO NOTHING;
