INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gum-droppers', 140608, '2005-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8iuu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8pip.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gum Droppers', 'People want sweets so much that the Goody Gumdrop Factory can''t keep up. They need your help. The gumdrop machine spits out gumdrops onto the top conveyor. You must gather three at a time and place them on the pile to make three or more of the same color in a row, vertically or horizontally. Pay particular attention to the color of the candy jars on the bottom right. You must fill both jars up to complete the level. If you don''t gather a gumdrop from the top conveyor before it gets to the end, it will fall to the bottom conveyor. If the bottom conveyor fills, a new row of gumdrops will be created. If the gumdrop pile gets to high, the game is over.' FROM games WHERE igdb_id = 140608 ON CONFLICT (game_id, language_code) DO NOTHING;
