INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Shifuujou: The Alternative Age', 'Touhou Shifuujou ...the Alternative Age is a fanmade Touhou Project shoot ''em up game developed by danmaq, best known for his later fangame Concealed the Conclusion. It is one of the earliest games made using the Danmakufu engine, as well as one of the earliest fanmade Touhou-style STGs.' FROM games WHERE igdb_id = 283830 ON CONFLICT (game_id, language_code) DO NOTHING;
