INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Portable Island: Te no Hira no Resort', 'Portable Island: Tenohira Resort is a Japanese Adventure/Simulation where the player spends time on a pretty resort island. The game is all about enjoying the leisurely atmosphere of a vacation. You can explore in natural settings like the jungle, volcano and desert, collect insects or seashells, or experience island life.' FROM games WHERE igdb_id = 207129 ON CONFLICT (game_id, language_code) DO NOTHING;
