INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hapland', 'Hapland is a point-and-click puzzle that was originally released as Flash game in 2005. In the game you have to find a way to open the portal by enlisting the help of the people who live in the world, while not getting them eaten by monsters or blown up by landmines.' FROM games WHERE igdb_id = 230604 ON CONFLICT (game_id, language_code) DO NOTHING;
