INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buzz! The Sports Quiz', 'This is the third game in the Buzz! series and was developed by Kuju Entertainment. Players answer questions asked by the Quizmaster (Buzz) using their Buzz! buzzers. The format is very similar to an actual gameshow, fit with a Quizmaster, his ''delicious'' sidekick (Rose), buzzers, a theme song and an audience which claps and laughs. In every type of game, players must choose from easy mode or hard mode.' FROM games WHERE igdb_id = 43520 ON CONFLICT (game_id, language_code) DO NOTHING;
