INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gumby vs. The Astrobots', 'Join the heroic Gumby as he embarks on a perilous journey to rescue his friends in Gumby vs. The Astrobots. Search for his friends as you meet a huge cast of bendable friends from the Gumby TV show, including Pokey, Prickle, and Goo. Use Gumby''s unique ability to morph, stretch and twist to foil the Astrobots. Traverse the classic Old West or the icy North Pole, even the mysterious Planet Astrobot!' FROM games WHERE igdb_id = 49297 ON CONFLICT (game_id, language_code) DO NOTHING;
