INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Flow', '2005 real-time mecha strategy game by Kogado Studio''s Iruka Team. Released for Windows PCs. Prequel to the 2006 title Blue Blaster. Created as an attempt to make a more beginner-friendly version of Power Dolls, however the gameplay resembles something akin to Rasetsu, also developed by Iruka Team. The story is told through Visual Novel sections along with events during combat sections.' FROM games WHERE igdb_id = 245680 ON CONFLICT (game_id, language_code) DO NOTHING;
