INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kouchuu Kakutou: Mushi 1 Grand Prix', 'A groundbreaking beetle battle game with intense, action-packed fights like never before! Over 30 different species of kabutomushi and kuwagatamushi (rhinoceros and stag beetles) appear in full CG and 3D models. Use enhancement items called "Suppli" (Supplement) on your beetles, equip them with special moves known as "Suppli Techniques", and customize your original battle strategies. Strive to become the ultimate Mushi-1 Fighter!' FROM games WHERE igdb_id = 122898 ON CONFLICT (game_id, language_code) DO NOTHING;
