INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventures in Odyssey and the Great Escape', 'Eugene has just invented a life-size virtual reality game and invites Michael and Mandy to be the first to try it out. But when Michael removes the Safety Protocols, the virtual reality game turns into a very real struggle, pitting Michael and Mandy against the Computer''s brain—a hyper-intelligent enemy known as Seepi Yu. Is this "GAME OVER?"' FROM games WHERE igdb_id = 66067 ON CONFLICT (game_id, language_code) DO NOTHING;
