INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Whom the Telling Changed', 'The people had always gathered on moonless nights to hear the stories, since the time of their ancestors'' ancestors. The heat of the fire and the glow in the storyteller''s eyes made the past present, and the path to the future clear. The power in the telling was immense, subtle, divine. What man would dare subvert it?' FROM games WHERE igdb_id = 217677 ON CONFLICT (game_id, language_code) DO NOTHING;
