INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hope Springs Eternal', 'In this second Carol Reed game, she has taken over the detective agency from her deceased friend. She doesn''t have many cases to solve, until another friend calls her about an acquaintance who seems to have gone missing.' FROM games WHERE igdb_id = 94227 ON CONFLICT (game_id, language_code) DO NOTHING;
