INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fate/Hollow Ataraxia', 'Fate/Hollow Ataraxia is a 2005 PC visual novel video game developed by TYPE-MOON and the sequel to Fate/Stay Night. The word "ataraxia" in the title is a Greek term for "tranquility", giving the title the combined meaning of "empty (or false) tranquility". The game also was ported to PlayStation Vita, adding full-voice acting, among other enhancements. This version was released in Japan on November 27, 2014.' FROM games WHERE igdb_id = 275640 ON CONFLICT (game_id, language_code) DO NOTHING;
