INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'O Sombrio: A Voz das Almas', 'O Sombrio: A Voz das Almas is a Brazilian horror game where you take on the role of Amir, a professor at the Center for the Study of Natural Phenomenons. After coming into contact with a book called Sinister Sapiens, you become cursed with something that will make you realize the existence of what many cannot see, hear, or feel. In the story, you''ll find letters, documents, and telegrams, which will help understand what happened to you and to many in that town.' FROM games WHERE igdb_id = 278832 ON CONFLICT (game_id, language_code) DO NOTHING;
