INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superbike GP', 'Experience the full on thrills and spills of a high-speed Superbike competition. You will have to drive fast, play hard and watch your back. There are miles and miles of unrelenting track to cover before you can be crowned the champion as you speed through chicanes, power-slide around corners as you race for the chequered flag.' FROM games WHERE igdb_id = 43328 ON CONFLICT (game_id, language_code) DO NOTHING;
