INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chainsaw Maniac', 'Chainsaw Maniac was a browser-based game made to promote the PlayStation 2 release of Resident Evil 4. Chainsaw Manaic involved moving left and right into incoming chainsaw Ganado to defeat them in in Nintendo "Game & Watch" styled graphics. Two competitions were also held where players could win a copy of Resident Evil 4 for PlayStation 2, a PlayStation 2 Chainsaw Controller, or a T-shirt designed for the competition.' FROM games WHERE igdb_id = 289402 ON CONFLICT (game_id, language_code) DO NOTHING;
