INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sonic-x-bowling--1', 299872, '2005-06-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co85of.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs49g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic X Bowling', 'Sonic X Bowling is an online Flash game published on the 4Kids TV website by 4Kids Entertainment on 11 June 2005 to promote the then-airing anime series, Sonic X. It is a simple Sonic X-themed game of bowling. The game is based around the traditional ten-pin bowling game. Here, the player assumes control of Sonic on a bowling lane with ten bowling pins at the end. The player can send Sonic down the bowling lane as a curled-up ball so he can knock down the pins like an actual bowling ball. When having to roll Sonic, he will spin in one place while a blue arrow automatically swings left and right in front of him. When Sonic is then thrown, he will head in the direction that the arrow was pointing in at the time of the throw, before making a small turn in the opposite direction. How Sonic is aimed will determine the number of pins knocked down.' FROM games WHERE igdb_id = 299872 ON CONFLICT (game_id, language_code) DO NOTHING;
