INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circuit Blasters', 'Circuit Blasters is like no other racing game on earth! Up to 4 players can battle head to head on over 20 roller coaster race tracks in a choice of spectacular worlds. Each track features hair-raising, jaw-dropping, heart-in-the-mouth dips and drops. Add in some turbo speed racing and power-up assisted battling for an awesome experience.' FROM games WHERE igdb_id = 221294 ON CONFLICT (game_id, language_code) DO NOTHING;
