INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleach Heat the Soul', 'Bleach: Heat the Soul is the first installment in the Heat the Soul fighting game series, released on March 24, 2005. The theme song for the game is *: Asterisk by Orange Range, which also happens to be the original opening theme for the anime. The game has a total of six characters, all of which derived from the Agent of the Shinigami arc.' FROM games WHERE igdb_id = 44488 ON CONFLICT (game_id, language_code) DO NOTHING;
