INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evil Days of Luckless John', 'Evil Days of Luckless John is the English title of Žhavé léto 3 1/2 which was the last game in the Horké léto trilogy. It is a point and click adventure focused on crazy humor, however this time around there are other genres presented as well - racing, stealth, fighting and shoot ‘em up.' FROM games WHERE igdb_id = 73397 ON CONFLICT (game_id, language_code) DO NOTHING;
