INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugby 2005', 'Rugby 2005 is a game in the Rugby series by EA Sports. The game allows players to play as many Rugby nations, both major and minor, and includes many tournaments, such as the Rugby World Cup, the Tri Nations, the Six Nations, and the Super 12. Rugby 2005 is the first EA Rugby title for Xbox, while the Windows version was canceled in the US.' FROM games WHERE igdb_id = 6019 ON CONFLICT (game_id, language_code) DO NOTHING;
