INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini Desktop Racing', 'Mini Desktop Racing lets you loose with a crazy selection of officially licensed Minis, each accurately rendered with distinctive performance abilities. Players race in a variety of mini cars around a variety of desktop areas. The game offers reasonably interactive courses by allowing players to "turn on fans" and "spill drinks" in attempts to hinder opponents.' FROM games WHERE igdb_id = 5007 ON CONFLICT (game_id, language_code) DO NOTHING;
