INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Moto', 'X-Moto is a free and open source 2D motocross platform game developed for Linux, FreeBSD, Mac OS X and Microsoft Windows, where physics play an all important role in the gameplay. The basic gameplay clones that of Elasto Mania, but the simulated physics are subtly different.' FROM games WHERE igdb_id = 122757 ON CONFLICT (game_id, language_code) DO NOTHING;
