INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asterix and Caesar''s Challenge', 'You accompany Astérix and Obélix in their adventures. The game is set up like the old school Batman Returns, or King of Dragons. You have an energy bar. Use your energy to perform two different attacks and beat the Roman army. Often mistaken for the P-CD-i release "Asterix: Caesar''s Challenge", this game was released for PC and is thought to be a fan-made 2d scroller beat-em-up developed by Belavi Team and taken from the original Arcade game "Asterix".' FROM games WHERE igdb_id = 223048 ON CONFLICT (game_id, language_code) DO NOTHING;
