INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 88: The Mini Suke Porisu', 'You are Momo Samejima, a special forces agent. Your mission is to assassinate the leader of an organization that''s secretly selling a potent new drug, Perorin. You''ll make use of guns and grenades as you sneak into a city and face off against enemies in 3D. She tackles thugs with swift kicks in her short, short skirt. She blasts away at goons in her stocking-accessorized, ultra-short china-look dress.' FROM games WHERE igdb_id = 43325 ON CONFLICT (game_id, language_code) DO NOTHING;
