INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Soccer: Winning Eleven 8 - Liveware Evolution', 'World Soccer: Winning Eleven 8: Liveware Evolution is an enhanced version of Winning Eleven 8 developed by Konami and released exclusively in Japan in 2005 for the PlayStation 2. This edition introduced online multiplayer functionality, making it one of the first entries in the series to support online play. It features updated team rosters, slight gameplay refinements, and the core mechanics of Winning Eleven 8.' FROM games WHERE igdb_id = 220946 ON CONFLICT (game_id, language_code) DO NOTHING;
