INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beetle Bomp', 'Experimental electricity-eating beetles have been released from a top secret laboratory. Sling colorful bugs at each other to make sets of three like-colored beetles, and prevent a much-dreaded infestation. Journey from the city to countryside while dealing with bees, butterflies, centipedes, and persnickety hard-shell bugs. Hilarious animated cartoons tell the story of Lylek, the electrician, and Martina, the insect expert, as they try to solve the buggy mystery before the lights go out for good!.' FROM games WHERE igdb_id = 52632 ON CONFLICT (game_id, language_code) DO NOTHING;
