INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This Is Football 2005', 'Building upon the roots of the franchise, This Is Football 205 provides gamers with a familiar yet enhanced gameplay experience, complete with even more features, players, teams and stadiums. The game''s global soccer experience is highlighted by more than 935 international and club teams from around the globe, along with 19,000 FIFPro licensed players from 32 different leagues, eight international tournaments and 28 unique stadiums. Utilizing the EyeToy USB camera, gamers can take snapshots of themselves and convert the high-resolution images of a gamer''s head into a full 3D model so that they can personally battle against the world''s best.' FROM games WHERE igdb_id = 43444 ON CONFLICT (game_id, language_code) DO NOTHING;
