INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DT Racer', 'Extreme tuner racing just hit a whole new level of no holds barred racing. DT Racer drops you on to 22 of the slickest tracks around the globe. Completely fine tune every inch of your car''s handling and performance with unlimited customization. And when you are done, put your foot to the floor and show them what you''ve got!' FROM games WHERE igdb_id = 44709 ON CONFLICT (game_id, language_code) DO NOTHING;
