INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-roots-gates-of-chaos', 47566, '2005-08-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/jtlqbv57sobwez7pffh9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm7hn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Roots: Gates of Chaos', 'The Roots: Gates of Chaos is an action role playing game set in a fantasy world. It is designed much like Diablo or many more similar ARPGs: there''s a small hub, a peaceful town, and several pathways leading to the "wilderness" locations, where you encounter monsters and go to fulfill quests. In town you could shop, travel to a different location (there are five towns in The Roots), learn some local news, get quests or enter a gladiator arena. The tasks you can get are mostly kill or fetch quests typical for many ARPGs and MMORPGs that can provide you with valuable items in case you succeed and also do it before a deadline, as all of them are time-limited. To add interest and replayability there is a randomly generated loot system, such as also in many more RPGs. The items you get come with different stats, that could improve your character''s primary abilities, like strength or agility, add damage or raise the defenses and magical resistance. The rarer the item the more modifiers and higher they are, but also such items require certain character level to wield them. The role playing system consists of a set of primary stats, usable skills and passive talents specific for each of the five character classes. Skills could be equipped and used on the game map: there are things like empowered attacks as rain of arrows, or something more original when for limited amount of time you could transform into an a giant spider that will let you bruteforce your way around. The visual style is somewhat cartoonish in appearance as in another Blizzard game - Warcraft III.Besides the single player mode, it''s possible to play together with up to four player characters on the same in-game locations. And at the same time on the arena you can challenge them to a fight.' FROM games WHERE igdb_id = 47566 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 47566 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
