INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Fighters: Maximum Impact - Maniax', 'The first-ever 3D version of King of Fighters has finally arrived, complete with all your favorite SNK characters. In King of Fighters: Maximum Impact, rival gangs are vying for the chance to rule the underworld of Southtown. As one of more than 16 fighters, you must prove that you''re the greatest fighter in the world in five gameplay modes, including Story, Versus, Survival, Practice, and Training. The game''s enhanced character movement lets you perform four new jumps, powerful combo moves, and the new Knock Back Attack.' FROM games WHERE igdb_id = 47322 ON CONFLICT (game_id, language_code) DO NOTHING;
