INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Super Karts', 'Racing across the tarmac only inches above the road, International Super Karts gives an adrenaline rush like nothing else. Using every ounce of your driving skill is a must in these high-speed, lightweight vehicles. Take part in a variety of championships, exhibition races and time trials to earn extra vehicles and claim the Karting crown.' FROM games WHERE igdb_id = 43332 ON CONFLICT (game_id, language_code) DO NOTHING;
