INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bongo Loves the Bible', 'Bongo Loves the Bible is an action adventure game where you control an orangutan named Bongo. There are four playable adventures that have a variety of challenges to complete. The adventures often include finding answers to questions or puzzles based on passages from the Bible. This game was intended to be a fun way to teach students more about the Bible.' FROM games WHERE igdb_id = 146262 ON CONFLICT (game_id, language_code) DO NOTHING;
