INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elemental Gelade: Tozasareshi Uta', 'Elemental Gelade: Tozasareshi Uta is a RPG based on the manga/anime Elemental Gelade. The story takes place in the world of Guardia where beings called Edel Raids coexist with humans, and can fuse with them by becoming a powerful weapon. The player controls five characters from the anime: Coud Van Giruet, Reverie ‘Ren’ Metherlence (the most powerful Edel Raid, fuses with Coud), Cisqua, Rowen and Kuea (another Edel Raid, fuses with Rowen). The team journeys from town to town and fights enemies and meets new original characters throughout an original story. In the turn-based battles, the player gives commands such as fight, fuse and help to the party members.' FROM games WHERE igdb_id = 49413 ON CONFLICT (game_id, language_code) DO NOTHING;
