INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Combat Elite: WWII Paratroopers', 'Supported by an army of more than 17,000 US and British paratroopers, you must stop the Nazis from occupying Europe during WWII. Fight with authentic weapons and vehicles alongside brave Allied troops through rolling hills, small farms, and war-torn cities throughout France, Holland, and Belgium. More than 40 varied missions re-create the toughest battles of WWII, including D-Day, Operation Market Garden, and the Battle of the Bulge.' FROM games WHERE igdb_id = 5784 ON CONFLICT (game_id, language_code) DO NOTHING;
