INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Every Party', 'One of two titles from former Capcom producer Yoichi Okamoto''s new studio. The Xbox 360''s first party game features characters from Sakura Momoko, over 30 mini game types, 400 types of costume items that can be freely added to the characters, and 37 types of roulettes. You can stock up to five roulettes as you work your way across a board, attempting to reach the goal before others. Up to four players can play mini games together, with full support for Xbox Live.' FROM games WHERE igdb_id = 70529 ON CONFLICT (game_id, language_code) DO NOTHING;
