INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doctor Who: The Last Dalek', 'Based on the 2005 episode of Doctor Who "Dalek", The Last Dalek is a browser game where you play as a Dalek trying to escape the vault. Throughout each level of the game, you slowly reacquire your abilities in preparation for facing the Doctor at the end of the game. Developed by New Media Collective.' FROM games WHERE igdb_id = 232823 ON CONFLICT (game_id, language_code) DO NOTHING;
