INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Izumo 0', 'The year was 1879, 12 years into the Meiji period. The stage was Yokohoma, the gateway of Western influences into Japan. In this era of scientific knowledge and industrialization, an organization of ghost busters was formed. It was the "Police Department Special Squad". The story follows these six young men and women as they fight against ghostly conspiracies, and learn about friendship, purpose, love, war, and the pursuit of happiness.' FROM games WHERE igdb_id = 153684 ON CONFLICT (game_id, language_code) DO NOTHING;
