INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sharin-no-kuni-the-girl-among-the-sunflowers--1', 7185, '2005-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co865y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8fhx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sharin no Kuni: The Girl Among the Sunflowers', 'Early summer. A society which imposes special "Duties" upon everyone who breaks the law. The individuals who oversee these criminals'' rehabilitation are the "Special Elite"ーa rank the protagonist, Kenichi Morita, hopes to attain. To do that, he must pass his final exam, for which he arrives at a certain country town. At the school Kenichi attends, he encounters girls bound by various “Duties.” Those obligated "to observe a 12-hour day" are forbidden from being awake for more than 12 hours per day, and those obligated "to remain in infancy" cannot grow up. It is meeting Natsumi Hinata, the girl who "cannot fall in love," that throws him out of gear. Soon, Kenichi makes a series of odd discoveries… his own grave, erected secretly on a clifftop; his patrimony, hidden deep inside a cavern. Kenichi finds that he must search for his own atonement in this dystopian society. What is the truth behind the Land of the Spinning Wheel? Discover for yourself through Kenichi''s eyes!' FROM games WHERE igdb_id = 7185 ON CONFLICT (game_id, language_code) DO NOTHING;
