INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cobra The Arcade', '"Cobra The Arcade" is a gun shooting game released by Namco (later Bandai Namco Games) in November 2005. It is based on Buichi Terasawa''s manga "Cobra" and the TV series "Space Cobra." The gameplay is enhanced by a controller that resembles the Psycho Gun, and cards that allow data saving and strengthening the Psycho Gun. It uses the system from Time Crisis 3, but a unique feature is the Psycho Shot, which locks on to enemies and takes down multiple enemies at once.' FROM games WHERE igdb_id = 303967 ON CONFLICT (game_id, language_code) DO NOTHING;
