INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy VII', 'Final Fantasy VII is an unlicensed "Shanzhai" demake of SquareSoft role-playing game of the same name, originally released for PlayStation in 1997. This two-dimensional "port" was developed and published by Chinese company Shenzhen Nanjing Technology for Subor, a Nintendo''s Family Computer clone console series (internationally known as the NES). The cartridge itself is unique, as it is structurally different from licensed Famicom cartridges in terms of hardware and programming.' FROM games WHERE igdb_id = 2406 ON CONFLICT (game_id, language_code) DO NOTHING;
