INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alfa: Antiterror', 'Alfa: Antiterror is a strategy video game created by Russian developer MiST Land South and published by Game Factory Interactive in Russia on January 20, 2005. In the same year, the North American company Strategy First published the game as well. The story of the game follows a Russian special forces Alpha Group. The player guides the actions of the detachment of an elite squad Alpha Group to fight terrorism. Many jobs in the game are based on historical events.' FROM games WHERE igdb_id = 52381 ON CONFLICT (game_id, language_code) DO NOTHING;
