INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty 2: Big Red One - Collector''s Edition', 'Call of Duty 2: Big Red One also has a Collector''s Edition that contains a bonus DVD with: - Four exclusive character skins for multiplayer gameplay – using Elite soldier models. - Interviews, MoCap/VO session footage of the in-game voice actors from the cast of Band of Brothers. - Interviews with WWII veterans of the Big Red One, including memories of in-game events. - Multiplayer map fly-through''s with DVD-style developer commentary (tips, interesting facts, etc.). - Behind the scenes with Treyarch, discussing the development of Call of Duty 2: Big Red One. - Concept and production art gallery (art, sketches, storyboards, renders, etc.).' FROM games WHERE igdb_id = 294561 ON CONFLICT (game_id, language_code) DO NOTHING;
