INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blokus Portable: Steambot Championship', 'Blokus Portable: Steambot Championship, known in Japan as Blokus Club with Bumpy Trot, is a 2005 puzzle video game developed and published by Irem Software Engineering for the PlayStation 2 and later ported to the PlayStation Portable in Japan. The PlayStation Portable version was later published outside Japan by Majesco. It is based on the board game Blokus and features characters from Steambot Chronicles (known in Japan as Bumpy Trot). Like in Steambot Chronicles, players are able to customize the appearance of their characters. Each player is given a pile of blocks that resemble Tetrads . Players must place blocks on the board starting at the corners and then extend it from the corners of the pieces they have placed. The game is over when no one can place any more pieces. The player with the fewest pieces remaining wins.' FROM games WHERE igdb_id = 42718 ON CONFLICT (game_id, language_code) DO NOTHING;
