INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris: The Grand Master 3 - Terror‑Instinct', 'This game was released in 2005. The game now runs on PC-based hardware, specifically the Taito Type X. The level system has been expanded in many forms with increasingly stricter requirements to reach the Grand Master rank. Modes include Easy, Sakura (a puzzle mode also seen in Tetris With Cardcaptor Sakura: Eternal Heart), the traditional Master mode, and Shirase (an extension of T.A. Death with even harsher speed, garbage, and levels beyond 999). It also features World and Classic Rules, the former added by Arika due to The Tetris Company''s recent policy changes.' FROM games WHERE igdb_id = 25024 ON CONFLICT (game_id, language_code) DO NOTHING;
