INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead to Rights: Reckoning', 'Fearless cop Jack Slate is back in the first installment of the Dead to Rights series on a handheld system. As Jack, you must navigate the corrupt underworld of Grant City to rescue the lost informant before it''s too late. Dead to Rights: Reckoning features a new storyline, as well as new moves and weapons.' FROM games WHERE igdb_id = 3010 ON CONFLICT (game_id, language_code) DO NOTHING;
