INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slotter Up Core 7: Dekitou da! Street Fighter II', 'Slotter Up Core 7: Dekitou da! Street Fighter II is a pachinko simulation based on the popular arcade hits series Street Fighter. The game features a perfect simulation of the pachinko machine with different levels of zoom, there also a sound & musics galleries and a picture gallerie with the pachinko machine flyer.' FROM games WHERE igdb_id = 55060 ON CONFLICT (game_id, language_code) DO NOTHING;
