INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saboteur', 'Saboteur is a creative, multi-level shooter developed by Howard Scott Warshaw in 1983 but never released. You are a robot named Hotot. A strange race of blue aliens is using your planet to launch a galaxy-destroying warhead. With the help of a yellow birdlike race, you must destroy the rocket, disarm the warhead, and prevent your planet''s destruction!' FROM games WHERE igdb_id = 230600 ON CONFLICT (game_id, language_code) DO NOTHING;
